{"cards": [{"node_code": "N_9afb5860077b1c7d", "definition": "水路运输中关于航道、航线及运河的规划、组织、调度与日常运营管理，涵盖通航秩序维护、航线网络布局及特定水域（如运河）的通行管理。", "boundary": "本节点聚焦于“管理”与“组织”层面，即如何利用现有水道进行运输组织。边界在于区分“工程技术”（航道疏浚、护岸、船闸结构归入航道工程）与“运营管理”（航线规划、通航调度、运河通行规则归入本节点）。若涉及运河的工程建设，归入航道工程；若涉及运河的通行管理与调度，归入本节点。", "includes": ["航线规划、网络布局及通航秩序管理", "运河、人工水道的通行组织与管理", "各类特定航线（如沿海、内河、国际航线）的运营技术与管理规范"], "excludes": ["航道、运河、船闸等基础设施的工程设计、施工与结构安全", "船舶本身的航行技术、操纵性能及航海仪器使用"], "sibling_distinctions": [{"other_code": "N_e288166af7250639", "rule": "本节点侧重航道建成后的“通航组织、航线规划与管理”，兄弟节点侧重航道的“疏浚、整治、护岸等工程技术”。"}, {"other_code": "N_9e8c9633409860d4", "rule": "本节点聚焦于“空间与路径”（水道、航线、运河）的管理，兄弟节点聚焦于“整体业务流程”（水运工作组织、调度、统计等综合管理）。"}], "cross_boundary_rule": "若内容涉及运河或航道的“工程建设与维护”，主挂载航道工程；若涉及“通航调度、航线规划、通行规则”，主挂载本节点。"}, {"node_code": "N_bd5fa9494719425e", "definition": "水路运输运营过程中的安全管理体系，涵盖安全法规、客货作业安全、防火、防污染、事故处理、气象灾害应对及劳动保护等技术与制度规范。", "boundary": "本节点聚焦于“安全”这一特定维度的技术与管理。边界在于区分“安全技术”与“一般技术管理”（如调度、装卸工艺归入其他兄弟节点，除非涉及安全规程）。若内容涉及船舶结构安全设计，归入船舶工程；若涉及港口设施结构安全，归入港口工程。本节点侧重运营过程中的风险防控、事故应急及合规性管理。", "includes": ["水路运输安全规章制度、标准及事故分析处理", "客运、货运及商务作业中的安全技术规程", "防火、防污染、防汛防台风等专项安全技术及劳动保护"], "excludes": ["船舶、港口设施的结构强度设计与建造安全（归入工程类）", "水路运输的经济效益、成本核算及运价制定（归入水路运输经济）"], "sibling_distinctions": [{"other_code": "N_9e8c9633409860d4", "rule": "本节点侧重“安全”专项（风险、事故、防护），兄弟节点侧重“综合运营”（调度、流程、统计）。"}, {"other_code": "N_a7e15a713fb19860", "rule": "本节点侧重装卸作业中的“安全规程与防护”，兄弟节点侧重装卸的“工艺流程、设备选型与效率优化”。"}], "cross_boundary_rule": "若内容涉及“安全设备的设计与制造”，主挂载相关工程节点；若涉及“安全操作规程、事故应急、安全管理”，主挂载本节点。"}, {"node_code": "N_fa5c96a445034c13", "definition": "全球范围内水路运输行业的整体概况、发展趋势、主要航运公司、国际航运组织及行业技术管理水平的综述性内容。", "boundary": "本节点聚焦于“宏观行业”与“国际视野”，侧重描述性、综述性内容。边界在于区分“行业概况”与“具体技术/经济分析”。若内容涉及具体国家的航运政策或经济数据，需视侧重而定：若为技术管理水平的国际比较或行业综述，归入本节点；若为纯经济分析，归入水路运输经济。本节点不包含具体的船舶设计或航道工程技术细节。", "includes": ["世界航运业的发展历史、现状与趋势综述", "主要国际航运组织、大型航运集团及行业格局", "国际航运技术管理水平的比较与概况"], "excludes": ["具体船舶的设计、建造与修理技术", "具体航道的疏浚、整治工程或具体港口的作业工艺"], "sibling_distinctions": [{"other_code": "N_9e8c9633409860d4", "rule": "本节点侧重“全球行业宏观概况”，兄弟节点侧重“具体水运业务的操作组织与管理流程”。"}, {"other_code": "N_f351ffdebeb4d928", "rule": "本节点侧重“行业技术与管理水平的综述”，兄弟节点侧重“运输成本、运价、投资等经济规律分析”。"}], "cross_boundary_rule": "若内容涉及“国际航运经济政策与贸易”，主挂载水路运输经济；若涉及“国际航运技术管理概况与行业综述”，主挂载本节点。"}]}
